const { validationResult } = require('express-validator');
const AppError = require('../utils/appError');

/**
 * @desc    Centralized Validation Middleware
 * @logic   Extracts validation errors generated by express-validator rules,
 *          formats them into a clean message, and forwards a 400 AppError to next().
 */
const validate = (req, res, next) => {
    const errors = validationResult(req);

    // If validation errors exist, halt the request before reaching the controller
    if (!errors.isEmpty()) {
        const formattedErrors = errors
            .array()
            .map((err) => `${err.path}: ${err.msg}`)
            .join(' | ');

        return next(new AppError(`Validation Error: ${formattedErrors}`, 400));
    }

    next();
};

module.exports = validate;